#include "../Source/Expansion/InstrumentModel.h"
#include "../Source/Expansion/MPEExpression.h"
#include "../Source/Expansion/ModulationMatrix.h"
#include "../Source/Expansion/MultisampleEngine.h"
#include <cassert>
#include <cmath>
#include <iostream>
#include <string>
#include <utility>
using namespace sampler;
static SampleZone z(const char* id,int kl,int kh,int vl,int vh,int rr=0){SampleZone s;s.id=id;s.sample={"sample-"+s.id,"/samples/"+s.id+".wav",48000,2,48000};s.keyLow=std::uint8_t(kl);s.keyHigh=std::uint8_t(kh);s.velocityLow=std::uint8_t(vl);s.velocityHigh=std::uint8_t(vh);s.rootKey=std::uint8_t((kl+kh)/2);s.roundRobinGroup=std::uint8_t(rr);return s;}
int main(){InstrumentModel m;assert(m.addZone(z("soft",48,72,1,63)));assert(m.addZone(z("hard",48,72,64,127)));auto a=m.select(60,40),b=m.select(60,100);assert(a.size()==1&&a[0].zone->id=="soft");assert(b.size()==1&&b[0].zone->id=="hard");assert(!m.addZone(z("bad",72,48,1,127)));assert(m.validate()); auto preset=m.serialize(); assert(!preset.empty()); InstrumentModel restored; assert(restored.deserialize(preset)); assert(restored.size()==m.size()); assert(restored.zones()[0].id=="soft"&&restored.zones()[1].velocityLow==64); auto corrupt=preset; corrupt[0]='X'; assert(!restored.deserialize(corrupt)&&restored.size()==2); auto truncated=preset; truncated.pop_back(); assert(!restored.deserialize(truncated)&&restored.size()==2); InstrumentModel crowded;for(int i=0;i<129;++i){auto zone=z(("layer-"+std::to_string(i)).c_str(),0,127,1,127);assert(crowded.addZone(std::move(zone)));}auto crowdedSelection=crowded.select(60,90);assert(crowdedSelection.size()==128&&crowdedSelection.overflowed());InstrumentModel rr;assert(rr.addZone(z("always",0,127,1,127)));assert(rr.addZone(z("rr-a",0,127,1,127,1)));assert(rr.addZone(z("rr-b",0,127,1,127,1)));auto r1=rr.select(60,100),r2=rr.select(60,100);assert(r1.size()==2&&r2.size()==2&&r1[1].zone->id!=r2[1].zone->id);MPEExpression mpe({MPEZoneConfig::Layout::Lower,15,48});assert(mpe.isMemberChannel(2)&&!mpe.isMemberChannel(1));mpe.process({MPEEvent::Type::PitchBend,2,60,0,16383});mpe.process({MPEEvent::Type::ChannelPressure,2,0,0,100});mpe.process({MPEEvent::Type::ControlChange,2,0,74,80});mpe.process({MPEEvent::Type::PolyPressure,2,60,0,64});auto e=mpe.forChannel(2);assert(e.pitchBendSemitones>47.9f);assert(std::abs(e.pressure-100.0f/127)<0.0001f);assert(std::abs(e.slide-80.0f/127)<0.0001f);assert(std::abs(mpe.perNotePressure(2,60)-64.0f/127)<0.0001f);mpe.process({MPEEvent::Type::ControlChange,2,0,64,0});assert(mpe.forChannel(2).sustain==0);assert(mpe.perNotePressure(2,200)==0.0f); mpe.process({MPEEvent::Type::PitchBend,1,0,0,12288}); mpe.process({MPEEvent::Type::ChannelPressure,1,0,0,90}); mpe.process({MPEEvent::Type::ControlChange,1,0,64,127}); auto combined=mpe.forChannel(2); assert(combined.pitchBendSemitones>71.9f&&combined.pitchBendSemitones<72.1f); assert(combined.pressure>=90.0f/127.0f&&combined.sustain==1.0f); mpe.process({MPEEvent::Type::ControlChange,1,0,1,127}); auto modInputs=mpe.modulationInputs(2,60,0.8f,0.25f,0.5f,0.7f); assert(modInputs.velocity==0.8f&&modInputs.modWheel==1.0f&&modInputs.slide>0.62f&&modInputs.lfo1==0.5f);MPEExpression upper({MPEZoneConfig::Layout::Upper,4,48});assert(upper.isMemberChannel(15)&&!upper.isMemberChannel(16)&&!upper.isMemberChannel(11));mpe.reset();assert(mpe.forChannel(2).pressure==0);ModulationMatrix matrix; ModulationInputs inputs; inputs.velocity=0.75f; inputs.slide=0.5f; assert(matrix.addRoute({ModSource::Velocity,ModDestination::GainDb,12.0f,true})); assert(matrix.addRoute({ModSource::Slide,ModDestination::Pan,0.8f,true})); assert(std::abs(matrix.evaluate(ModDestination::GainDb, -6.0f, -24.0f, 12.0f, inputs)-3.0f)<0.0001f); assert(std::abs(matrix.evaluate(ModDestination::Pan, 0.0f, -1.0f, 1.0f, inputs)-0.4f)<0.0001f); auto disabled=*matrix.route(0); disabled.enabled=false; assert(matrix.setRoute(0,disabled)); assert(matrix.evaluate(ModDestination::GainDb,-6.0f,-24.0f,12.0f,inputs)==-6.0f); assert(!matrix.setRoute(99,disabled)); assert(matrix.removeRoute(0)&&matrix.size()==1); Lfo lfo; lfo.configure(2.0f,Lfo::Shape::Square); assert(lfo.next(48000.0f)==1.0f); lfo.reset(0.75f); assert(lfo.next(48000.0f)==-1.0f); InstrumentModel playbackModel; auto playbackZone=z("playback",60,60,1,127); playbackZone.rootKey=60; assert(playbackModel.addZone(playbackZone)); float sampleL[8]={1,1,1,1,1,1,1,1}; float sampleR[8]={1,1,1,1,1,1,1,1}; ZoneAudio zoneAudio{&playbackModel.zones()[0],sampleL,sampleR,8,48000.0}; MultisampleEngine engine; assert(engine.setInstrument(playbackModel,&zoneAudio,1)); ModulationMatrix voiceMatrix; assert(voiceMatrix.addRoute({ModSource::Velocity,ModDestination::GainDb,6.0f,true})); assert(voiceMatrix.addRoute({ModSource::Lfo1,ModDestination::Pan,0.25f,true})); engine.setModulationMatrix(voiceMatrix); engine.configureLfo(5.0f,Lfo::Shape::Triangle); engine.setMPEZoneConfig({MPEZoneConfig::Layout::Lower,15,48.0f}); engine.setOutputSampleRate(48000.0); engine.handleMidi({EngineMidiEvent::Type::NoteOn,2,60,0,127}); assert(engine.activeVoices()==1); float outL[4]={0,0,0,0},outR[4]={0,0,0,0}; engine.render(outL,outR,4,48000.0); assert(outL[0]>=0.0f&&outL[3]>0.0f&&outR[3]>0.0f); engine.handleMidi({EngineMidiEvent::Type::NoteOff,2,60,0,0}); assert(engine.activeVoices()==1); float tailL[4096]={},tailR[4096]={}; engine.render(tailL,tailR,4096,48000.0); assert(engine.activeVoices()==0); InstrumentModel invalidModel; assert(!engine.setInstrument(invalidModel,&zoneAudio,1)); std::cout<<"Sampler Expansion tests passed\n";}
